    'faq_note' => 'Answers руу common асуултууд.',
    'faq_q1' => '<strong>What байна TropaTT?</strong><br>A free нээх-эх сурвалж self-hosted CRM, даалгавар manager, and төсөл management platform.',
    'faq_q10' => 'Who байна the developer?',
    'faq_q10_answer' => '<strong>Anton Barinov</strong>, a PHP developer.',
    'faq_q2' => '<strong>Is it a CRM or a даалгавар manager?</strong><br>Both. A CRM д зориулсан үйлчлүүлэгчид and counterparties, a даалгавар manager д зориулсан даалгавар, plus төсөл management, chat, хуанли, and AI.',
    'faq_q3' => '<strong>Is it suitable д зориулсан freelancers?</strong><br>Yes. There байна no хамгийн бага баг хэмжээ. A single хэрэглэгч gets CRM, даалгавар, an AI day төлөвлөгөө, and chat гүй per-seat fees.',
    'faq_q4' => '<strong>Does it work дээр shared hosting?</strong><br>Yes. PHP 8.1+ and MySQL байна enough. The browser installer configures everything.',
    'faq_q5' => '<strong>Are there limits дээр хэрэглэгчид and даалгавар?</strong><br>No. Unlimited хэрэглэгчид, даалгавар, төслүүд, and үйлчлүүлэгчид. The зөвхөн limitation байна server capacity.',
    'faq_q6' => '<strong>Where байна the өгөгдөл stored?</strong><br>100% дээр таны server. The system never syncs өгөгдөл руу the cloud.',
    'faq_q7' => '<strong>What AI tools байна боломжтой?</strong><br>20+ tools: idea exploration, day/долоо хоног төлөвлөгөөнүүд, summaries, checklists, эрсдэлүүд, meeting preparation.',
    'faq_q8' => '<strong>Is there an API?</strong><br>Yes, a REST API тай an OpenAPI 3.1 spec generated аас code.',
    'faq_q9' => '<strong>Can it be customized?</strong><br>Yes. PHP code, модулиуд, webhooks, API, workflow rules, custom талбарууд, үүргүүд, and access rights.',
    'faq_title' => 'Frequently asked асуултууд',
    'gantt_intro' => 'Gantt displays төсөл даалгавар дээр a хугацааны шугам. It lets та төлөвлөгөө deadlines, track dependencies, and monitor resource overload.',
    'gantt_item1' => 'Each даалгавар байна displayed as a bar дээр the хугацааны шугам.',
    'gantt_item2' => 'Dependencies: даалгавар B depends дээр даалгавар A — shown дээр Gantt as a link.',
