    'mcp_title' => 'AI Agents (MCP)',
    'mcp_note' => 'Connect Claude Code, Codex, ChatGPT, and other AI agents руу the CRM.',
    'mcp_why' => '<strong>Why:</strong> MCP allows AI agents руу read and удирдах таны даалгавар, төслүүд, үйлчлүүлэгчид, and chats through a unified protocol — тай the same access зөвшөөрлүүд as the web UI.',
    'mcp_intro' => 'TropaTT includes a built-дотор MCP (Model Context Protocol) server — the same protocol understood аар Claude Code, Codex, ChatGPT, and other compatible AI agents.',
    'mcp_item1' => '<strong>620 MCP tools + 6 resources</strong> — даалгавар, төслүүд, үйлчлүүлэгчид, contacts, chats, хуанли, шинжилгээ, мэдлэг сан.',
    'mcp_item2' => '<strong>Same өгөгдөл and rules</strong> — every хүсэлт goes through REST API and RBAC checks, just like the web interface.',
    'mcp_item3' => '<strong>Security</strong> — sensitive өгөгдөл (tokens, password hashes, API keys) байна filtered; writes require appropriate зөвшөөрлүүд.',
    'mcp_item4' => '<strong>Endpoint:</strong> POST /api/index.php?route=api/v1/mcp, authentication via Bearer token.',
    'mcp_docs_link' => 'Full MCP documentation:',
    'usage_title' => 'Usage Examples',
    'usage_note' => 'Concrete scenarios д зориулсан different үүргүүд and industries.',
    'usage_why' => '<strong>Why:</strong> these examples show how TropaTT байна used дотор real workflows — аас incoming хүсэлт руу дууссан даалгавар.',
    'usage_cycle_heading' => 'Full үйлчлүүлэгч work cycle',
    'usage_step1' => '<strong>Capture</strong> — idea, үйлчлүүлэгч хүсэлт, problem, or incoming lead.',
    'usage_step2' => '<strong>Analysis</strong> — дээр таны own or тай AI: scope, эрсдэлүүд, feasibility, approach.',
    'usage_step3' => '<strong>Structure</strong> — into төслүүд, даалгавар, subtasks, checklists, assignees, deadlines.',
    'usage_step4' => '<strong>Coordination</strong> — via chat, сэтгэгдлүүд, @mentions, мэдэгдлүүд.',
    'usage_step5' => '<strong>Execution</strong> — даалгавар lists, Kanban, My Day, My долоо хоног.',
    'usage_step6' => '<strong>Tracking</strong> — Gantt, dashboards, шинжилгээ, load, эрсдэл signals.',
    'usage_step7' => '<strong>Automation</strong> — workflow rules, SLA, webhooks, approval chains.',
    'usage_examples_heading' => 'Concrete examples',
    'usage_ex1' => '<strong>Freelancer:</strong> үйлчлүүлэгч хүсэлт → AI analyzes → даалгавар төлөвлөгөө → My Day → execution → үйлчлүүлэгч chat → done.',
    'usage_ex2' => '<strong>Agency:</strong> үйлчлүүлэгч brief → AI decomposes → төсөл + milestones → Kanban → Gantt tracking → үйлчлүүлэгч тайлан → шинжилгээ.',
    'usage_ex3' => '<strong>Service company:</strong> counterparty → төсөл → installation даалгавар → Gantt → daily төлөвлөгөөнүүд → SLA monitoring → act signing.',
    'usage_ex4' => '<strong>B2B operations:</strong> company → contacts → даалгавар + approvals → reminders → webhook → хянах самбар.',
    'tech_title' => 'Tech Stack & Numbers',
