    'tech_stack_heading' => 'Technology Stack',
    'tech_stack1' => '<strong>Backend:</strong> PHP 8.1+, custom microkernel. Zero external dependencies. No Laravel/Symfony/Doctrine.',
    'tech_stack2' => '<strong>Database:</strong> MySQL.',
    'tech_stack3' => '<strong>Frontend:</strong> PHP-rendered MPA + Bootstrap 5 + custom vanilla JS ES5+ модулиуд. No React/Vue/Angular. No bundler.',
    'tech_stack4' => '<strong>Architecture:</strong> API-first. Web UI uses REST API д зориулсан бүгд өгөгдөл. Zero direct DB calls аас the web layer.',
    'tech_stack5' => '<strong>Security:</strong> Dual authentication (cookie + CSRF д зориулсан web, Bearer д зориулсан API). RBAC. SSRF protection. Rate limiting.',
